// TestActionNames asserts every announced commands action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Children,
		provider.Current,
		provider.Get,
		provider.Parent,
		provider.Query,
		provider.Run,
		provider.Siblings,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

